import{_ as t,o as d,c as o,ax as r}from"./chunks/framework.Buhf-QP1.js";const m=JSON.parse(`{"title":"Widget Runtime Reference","description":"Properties, methods, and events on the sdk object passed to your widget's init(sdk) function, including sdk.connectors and sdk.web","frontmatter":{"description":"Properties, methods, and events on the sdk object passed to your widget's init(sdk) function, including sdk.connectors and sdk.web"},"headers":[],"relativePath":"sdk/runtime-reference.md","filePath":"sdk/runtime-reference.md"}`),c={name:"sdk/runtime-reference.md"};function n(i,e,s,a,h,l){return d(),o("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/sdk/runtime-reference.md for this page in Markdown format</div><h1 id="widget-runtime-reference" tabindex="-1">Widget Runtime Reference <a class="header-anchor" href="#widget-runtime-reference" aria-label="Permalink to &quot;Widget Runtime Reference&quot;">​</a></h1><p>This page documents the <code>sdk</code> object the platform passes to your widget&#39;s <code>init(sdk)</code> function. It is the single SDK entry point for widget code: it carries the widget&#39;s runtime API plus the connectors client (<code>sdk.connectors</code>) and the community Web SDK (<code>sdk.web</code>).</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>ShadowRoot</code></td><td>The widget&#39;s shadow root (mount target)</td></tr><tr><td><code>shadowRoot</code></td><td><code>ShadowRoot</code></td><td>Alias for <code>root</code> — the same shadow root reference</td></tr><tr><td><code>document</code></td><td><code>Document</code></td><td>Global document reference</td></tr><tr><td><code>version</code></td><td><code>string</code></td><td>SDK version (e.g. <code>&quot;1.5.2&quot;</code>)</td></tr><tr><td><code>connectors</code></td><td>Connectors client</td><td>The connectors client, shared by every widget on the page (<code>configure()</code> affects all of them). See <a href="/docs/sdk/connectors-sdk/overview.html">Connectors SDK</a></td></tr><tr><td><code>web</code></td><td>Web SDK | <code>undefined</code></td><td>The community Web SDK. <code>undefined</code> where the host page has none (embedded widgets on external sites, Skilljar). See <a href="/docs/sdk/web-sdk/overview.html">Web SDK</a></td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>getContainer()</code></td><td><code>ShadowRoot</code></td><td>Returns the widget&#39;s shadow root — same reference as <code>root</code>/<code>shadowRoot</code>, recommended mount target for framework apps (React, Vue, etc.)</td></tr><tr><td><code>getProps&lt;T&gt;()</code></td><td><code>T</code></td><td>Current widget props (from configuration)</td></tr><tr><td><code>setProps(props)</code></td><td><code>void</code></td><td>Update props (emits <code>propsChanged</code>)</td></tr><tr><td><code>getVersionInfo()</code></td><td><code>VersionInfo</code></td><td><code>{ version, gitSha, buildTime }</code></td></tr><tr><td><code>whenReady()</code></td><td><code>Promise&lt;SDK&gt;</code></td><td>Resolves once initialization completes</td></tr><tr><td><code>$(selector)</code></td><td><code>Element | null</code></td><td>Shorthand for <code>shadowRoot.querySelector(selector)</code></td></tr><tr><td><code>$$(selector)</code></td><td><code>Element[]</code></td><td>Shorthand for <code>shadowRoot.querySelectorAll(selector)</code> — returns an array, not a NodeList</td></tr><tr><td><code>on(event, handler)</code></td><td><code>() =&gt; void</code></td><td>Subscribe to an event (returns unsubscribe fn)</td></tr><tr><td><code>off(event, handler)</code></td><td><code>void</code></td><td>Unsubscribe from an event</td></tr><tr><td><code>emit(event, data?)</code></td><td><code>void</code></td><td>Emit a custom event</td></tr></tbody></table><h2 id="built-in-events" tabindex="-1">Built-in Events <a class="header-anchor" href="#built-in-events" aria-label="Permalink to &quot;Built-in Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Payload</th><th>Trigger</th></tr></thead><tbody><tr><td><code>propsChanged</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>Widget configuration changes</td></tr><tr><td><code>destroy</code></td><td><code>undefined</code></td><td>Widget removed from DOM</td></tr><tr><td><code>error</code></td><td><code>{ message: string, error?: Error }</code></td><td>Module load or initialization error</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/docs/custom-widgets/v2/core-concepts.html">Widget Runtime</a> — Runtime model, lifecycle, props, and design tokens</li><li><a href="/docs/custom-widgets/v2/configurable-widgets.html">Configurable Widgets</a> — Let editors customize your widget via a form in the <strong>No-Code Builder</strong></li><li><a href="/docs/custom-widgets/v2/using-react.html">Using React</a> — Build widgets with React</li><li><a href="/docs/sdk/concepts.html">SDK Concepts</a> — How the runtime, <code>sdk.connectors</code> and <code>sdk.web</code> relate</li></ul>',11)])])}const f=t(c,[["render",n]]);export{m as __pageData,f as default};
